using namespace fedspatial; namespace fs=std::filesystem;
static Matrix load(const fs::path&p){Matrix x;if(!read_matrix(p.string(),&x))throw std::runtime_error("missing "+p.string());return x;}
int main(){try{fs::path f="sync_gpu/tests/fixtures/figure1_reference",o="results/figure1_cpp_gpu_faithful/parity";fs::create_directories(o);Matrix k=load(f/"knots.txt"),g(5,1),mu(100,1),sig(100,100);double gv[]={-1,2,3,-2,1};for(int i=0;i<5;i++)g(i,0)=gv[i];std::vector<WorkerInput>w;for(int id=0;id<10;id++){Matrix d=load(f/("worker_"+std::to_string(id)+".txt"));WorkerInput q{Matrix(100,2),Matrix(100,1),Matrix(100,5)};for(int i=0;i<100;i++){q.sites(i,0)=d(i,0);q.sites(i,1)=d(i,1);q.z(i,0)=d(i,2);for(int j=0;j<5;j++)q.x(i,j)=d(i,j+3);}w.push_back(q);}GlobalParameters p{g,mu,sig,.25,1.,.11};GpuContext c(0);auto r=run_p_synchronous_round(c,w,k,p);std::ofstream csv(o/"p_iteration1_full_parity.csv");csv<<"quantity,index,python_value,cpp_value,abs_error,rel_error\n";double mx=0,em=0,es=0,eg=0,ed=0,ea=0,eb=0;auto row=[&](const char*q,int i,double py,double cu,double&part){double e=std::abs(py-cu);part=std::max(part,e);mx=std::max(mx,e);csv<<q<<','<<i<<','<<std::setprecision(17)<<py<<','<<cu<<','<<e<<','<<e/std::max(1e-300,std::abs(py))<<'\n';};Matrix pym=load(f/"p_initial_global_mu.txt"),pys=load(f/"p_initial_global_sigma.txt"),pyg=load(f/"p_initial_gamma_new.txt"),pjt=load(f/"p_initial_joint_updated_delta_alpha_beta.txt");for(int i=0;i<100;i++)row("mu",i,pym(i,0),r.parameters.mu(i,0),em);for(int i=0;i<10000;i++)row("Sigma",i,pys.a[i],r.parameters.sigma.a[i],es);for(int i=0;i<5;i++)row("gamma",i,pyg(i,0),r.parameters.gamma(i,0),eg);row("delta",0,pjt(0,0),r.parameters.delta,ed);row("alpha",0,pjt(1,0),r.parameters.alpha,ea);row("beta",0,pjt(2,0),r.parameters.range,eb);std::cout<<"P_ITERATION1_MU_MAX_ERROR="<<em<<"\nP_ITERATION1_SIGMA_MAX_ERROR="<<es<<"\nP_ITERATION1_GAMMA_MAX_ERROR="<<eg<<"\nP_ITERATION1_DELTA_ERROR="<<ed<<"\nP_ITERATION1_ALPHA_ERROR="<<ea<<"\nP_ITERATION1_BETA_ERROR="<<eb<<"\nP_ITERATION1_COMPLETE_STATE_MAX_ERROR="<<mx<<"\nP_ITERATION1_PARITY="<<(mx<1e-8?"PASS":"FAIL")<<"\n";return mx<1e-8?0:1;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 2;}}
